1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"math"
9		"math/big"
10		"regexp"
11		"sort"
12		"strconv"
13		"strings"
14		"unicode/utf16"
15		"unicode/utf8"
16	)
17	
18	// Point 是一条序列上某个时间戳的采样值。
19	type Point struct {
20		Timestamp int64   `json:"timestamp"`
21		Value     float64 `json:"value"`
22	}
23	
24	// SeriesView 是结果输出用的一条序列视图，标签按键升序呈现。
25	type SeriesView struct {
26		Name   string            `json:"name"`
27		Labels map[string]string `json:"labels"`
28		Points []Point           `json:"points"`
29	}
30	
31	// QuerySeries 是查询结果中的一条序列：完整身份与区间内点的个数及算术平均值。
32	type QuerySeries struct {
33		Name    string            `json:"name"`
34		Labels  map[string]string `json:"labels"`
35		Count   int               `json:"count"`
36		Average float64           `json:"average"`
37	}
38	
39	// QueryResult 是一次区间均值查询成功后的结果，只读，不改变存储。
40	type QueryResult struct {
41		Status string        `json:"status"`
42		Op     string        `json:"op"`
43		Series []QuerySeries `json:"series"`
44	}
45	
46	// BatchResult 是一批采样点写入成功后的结果。
47	type BatchResult struct {
48		Status     string       `json:"status"`
49		Added      int          `json:"added"`
50		Duplicates int          `json:"duplicates"`
51		Series     []SeriesView `json:"series"`
52	}
53	
54	// SeriesRef 标识一条序列：指标名加完整标签集合。
55	// 缺少某个标签与该标签值为空字符串属于不同序列。
56	type SeriesRef struct {
57		Name   string            `json:"name"`
58		Labels map[string]string `json:"labels"`
59	}
60	
61	// Conflict 描述同一序列同一时间戳已存在不同的值。
62	type Conflict struct {
63		Series    SeriesRef `json:"series"`
64		Timestamp int64     `json:"timestamp"`
65		Existing  float64   `json:"existing"`
66		Submitted float64   `json:"submitted"`
67	}
68	
69	// LineError 是一行（一批）输入失败后的结构化结果。
70	// Line 由命令入口按从 1 开始的行号填入；Index 为采样点在批次内从 1 开始的位置，
71	// 整行 JSON 无法解析或不是数组时 Index 为零并省略。
72	type LineError struct {
73		Status   string    `json:"status"`
74		Line     int       `json:"line,omitempty"`
75		Index    int       `json:"index,omitempty"`
76		Error    string    `json:"error"`
77		Conflict *Conflict `json:"conflict,omitempty"`
78	}
79	
80	// MetricStore 保存一次命令运行期间已写入的指标数据，仅存在于内存中，进程结束即丢弃。
81	type MetricStore struct {
82		series map[seriesID]*storedSeries
83	}
84	
85	// seriesID 是序列的规范身份，标签书写顺序不影响身份。
86	type seriesID struct {
87		name string
88		// sig 为排序后标签键值对的长度前缀拼接，避免不同写法产生碰撞。
89		sig string
90	}
91	
92	type storedSeries struct {
93		ref    SeriesRef
94		points map[int64]float64
95	}
96	
97	// NewMetricStore 创建一个空的指标存储。
98	func NewMetricStore() *MetricStore {
99		return &MetricStore{series: make(map[seriesID]*storedSeries)}
100	}
101	
102	// cloneLabels 返回标签集合的独立副本；空标签仍复制为非 nil 的空集合，
103	// 调用方对副本的增删改不影响存储中的序列身份。
104	func cloneLabels(labels map[string]string) map[string]string {
105		out := make(map[string]string, len(labels))
106		for k, v := range labels {
107			out[k] = v
108		}
109		return out
110	}
111	
112	func sortedKeys(m map[string]string) []string {
113		keys := make([]string, 0, len(m))
114		for k := range m {
115			keys = append(keys, k)
116		}
117		sort.Strings(keys)
118		return keys
119	}
120	
121	func makeSeriesID(name string, labels map[string]string) seriesID {
122		var b strings.Builder
123		for _, k := range sortedKeys(labels) {
124			v := labels[k]
125			fmt.Fprintf(&b, "%d:%s;%d:%s;", len(k), k, len(v), v)
126		}
127		return seriesID{name: name, sig: b.String()}
128	}
129	
130	// labelPair 是标签键值对字典序比较的单元。
131	type labelPair struct {
132		Key, Value string
133	}
134	
135	func sortedPairs(labels map[string]string) []labelPair {
136		keys := sortedKeys(labels)
137		pairs := make([]labelPair, len(keys))
138		for i, k := range keys {
139			pairs[i] = labelPair{Key: k, Value: labels[k]}
140		}
141		return pairs
142	}
143	
144	func compareLabelPairs(a, b []labelPair) int {
145		n := len(a)
146		if len(b) < n {
147			n = len(b)
148		}
149		for i := 0; i < n; i++ {
150			if a[i].Key != b[i].Key {
151				return strings.Compare(a[i].Key, b[i].Key)
152			}
153			if a[i].Value != b[i].Value {
154				return strings.Compare(a[i].Value, b[i].Value)
155			}
156		}
157		switch {
158		case len(a) < len(b):
159			return -1
160		case len(a) > len(b):
161			return 1
162		}
163		return 0
164	}
165	
166	var (
167		jsonIntegerRE = regexp.MustCompile(`^-?(0|[1-9][0-9]*)$`)
168		jsonNumberRE  = regexp.MustCompile(`^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$`)
169	)
170	
171	// ProcessLine 处理一行非空输入：JSON 数组为写入批次，JSON 对象为查询/操作。
172	// 成功时返回 BatchResult 或 *QueryResult；失败返回 *LineError（Index 始终为零）。
173	func (s *MetricStore) ProcessLine(line string) (any, *LineError) {
174		top, ok, lerr := decodeTopValue(line)
175		if lerr != nil {
176			return nil, lerr
177		}
178		switch ok {
179		case '[':
180			var items []json.RawMessage
181			if err := json.Unmarshal(top, &items); err != nil {
182				return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
183			}
184			return s.ingestItems(items)
185		case '{':
186			return s.queryFromObject(top)
187		default:
188			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
189		}
190	}
191	
192	// IngestLine 解析并写入一行（一批）采样点。成功返回 BatchResult；
193	// 失败返回 *LineError，此时此前各批数据保留、本批不写入任何数据。
194	func (s *MetricStore) IngestLine(line string) (*BatchResult, *LineError) {
195		top, ok, lerr := decodeTopValue(line)
196		if lerr != nil {
197			return nil, lerr
198		}
199		if ok != '[' {
200			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples"}
201		}
202		var items []json.RawMessage
203		if err := json.Unmarshal(top, &items); err != nil {
204			return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
205		}
206		return s.ingestItems(items)
207	}
208	
209	// QueryLine 解析并执行一行查询对象。成功返回 QueryResult；查询只读，不改变存储。
210	func (s *MetricStore) QueryLine(line string) (*QueryResult, *LineError) {
211		top, ok, lerr := decodeTopValue(line)
212		if lerr != nil {
213			return nil, lerr
214		}
215		if ok != '{' {
216			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
217		}
218		return s.queryFromObject(top)
219	}
220	
221	// validateLineText 在 JSON 解析之前强制整行文本合法：原始字节必须是合法
222	// UTF-8，字符串内的 Unicode 转义必须表示有效字符。编码层/JSON 解析器会把
223	// 非法字节或未配对代理项静默替换成 U+FFFD，使损坏文本混入合法序列（被误判为
224	// 重复、冲突或错误命中查询），因此这里一律拒绝而不是修补后继续。
225	//
226	// 逐字节扫描、只在字符串内部识别转义：跳过词法空白与全部非字符串 token。
227	// 被转义的反斜杠（\\）后的 "uXXXX" 只是普通文本，不会被当成 Unicode 转义。
228	func validateLineText(line string) *LineError {
229		if !utf8.ValidString(line) {
230			return &LineError{Status: "error", Error: "invalid JSON: input is not valid UTF-8 text"}
231		}
232		inString := false
233		for i := 0; i < len(line); i++ {
234			c := line[i]
235			if !inString {
236				if c == '"' {
237					inString = true
238				}
239				continue
240			}
241			switch c {
242			case '"':
243				inString = false
244			case '\\':
245				if i+1 >= len(line) {
246					break // 悬空反斜杠：交给 JSON 解析器报错
247				}
248				if line[i+1] != 'u' {
249					i++ // 单字符转义（\\、\"、\n 等），跳过被转义字符
250					continue
251				}
252				// i 指向 '\'，i+1 指向 'u'；转义占据 i..i+5。
253				r, size := decodeJSONHexEscape(line, i+1)
254				if size == 0 {
255					return &LineError{Status: "error", Error: "invalid JSON: invalid Unicode escape sequence"}
256				}
257				if !utf16.IsSurrogate(r) {
258					i += 5
259					continue
260				}
261				if r >= 0xDC00 {
262					// 单独出现的低代理项。
263					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
264				}
265				// 高代理项后必须紧接另一个表示低代理项的 \uXXXX 转义。
266				loPos := i + 6 // 第一个转义之后的字符位置
267				if loPos+1 >= len(line) || line[loPos] != '\\' || line[loPos+1] != 'u' {
268					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
269				}
270				lo, loSize := decodeJSONHexEscape(line, loPos+1)
271				if loSize == 0 || lo < 0xDC00 || lo > 0xDFFF {
272					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
273				}
274				i = loPos + loSize // 跳到第二转义的最后一个十六进制位，循环自增后越出
275			}
276		}
277		return nil
278	}
279	
280	// decodeJSONHexEscape 解析 line[pos:] 处的 "uXXXX"（pos 指向 'u'），
281	// 返回其码元与占用字节数（固定为 5）；不足四个十六进制数字时 size 为 0。
282	func decodeJSONHexEscape(line string, pos int) (rune, int) {
283		if pos+4 >= len(line) {
284			return 0, 0
285		}
286		var v rune
287		for j := pos + 1; j <= pos+4; j++ {
288			c := line[j]
289			var d rune
290			switch {
291			case c >= '0' && c <= '9':
292				d = rune(c - '0')
293			case c >= 'a' && c <= 'f':
294				d = rune(c-'a') + 10
295			case c >= 'A' && c <= 'F':
296				d = rune(c-'A') + 10
297			default:
298				return 0, 0
299			}
300			v = v<<4 | d
301		}
302		return v, 5
303	}
304	
305	// decodeTopValue 解析单行中唯一的 JSON 值并返回其原始内容与首个非空白字节
306	// （'[' 或 '{'）。整个值无法解析、为空或存在尾随内容时返回 *LineError。
307	func decodeTopValue(line string) (json.RawMessage, byte, *LineError) {
308		if lerr := validateLineText(line); lerr != nil {
309			return nil, 0, lerr
310		}
311		dec := json.NewDecoder(strings.NewReader(line))
312		var top json.RawMessage
313		if err := dec.Decode(&top); err != nil {
314			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
315		}
316		// 第一个 JSON 值之后只允许输入结束（Decoder 自动跳过尾随空白）。
317		if err := dec.Decode(new(json.RawMessage)); err != io.EOF {
318			if err == nil {
319				err = fmt.Errorf("unexpected content after the JSON value")
320			}
321			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
322		}
323		trimmed := strings.TrimSpace(string(top))
324		if len(trimmed) == 0 || (trimmed[0] != '[' && trimmed[0] != '{') {
325			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
326		}
327		return top, trimmed[0], nil
328	}
329	
330	// fieldReader 从 dec 读取并校验当前字段的值，写入调用方持有的结果。
331	// 采样点与查询对象各自注册自己允许的字段及字段含义。
332	type fieldReader func(dec *json.Decoder) error
333	
334	// parseStrictObject 是写入采样点与查询对象共用的严格对象校验骨架：
335	// 仅允许 fields 中列出的字段（未知字段先于判重被拒绝），同一对象内按转义还原
336	// 后的字段名判重（即使两个值相同也拒绝；判重不跨对象、不跨层级），按输入次序
337	// 逐字段调用对应的 fieldReader，对象结束后要求输入恰好耗尽，最后按 required
338	// 的顺序报告缺失的必填字段。notObjectMsg 与 trailingMsg 由调用方给出，
339	// 保留各自输入的措辞。
340	func parseStrictObject(raw json.RawMessage, notObjectMsg, trailingMsg string, required []string, fields map[string]fieldReader) error {
341		dec := json.NewDecoder(bytes.NewReader(raw))
342		dec.UseNumber()
343	
344		tok, err := dec.Token()
345		if err != nil {
346			return err
347		}
348		if d, ok := tok.(json.Delim); !ok || d != '{' {
349			return fmt.Errorf("%s", notObjectMsg)
350		}
351	
352		present := make(map[string]bool)
353		for dec.More() {
354			keyTok, err := dec.Token()
355			if err != nil {
356				return err
357			}
358			key := keyTok.(string)
359			read, ok := fields[key]
360			if !ok {
361				return fmt.Errorf("unknown field %q", key)
362			}
363			if present[key] {
364				return fmt.Errorf("duplicate field %q", key)
365			}
366			present[key] = true
367			if err := read(dec); err != nil {
368				return err
369			}
370		}
371		if _, err := dec.Token(); err != nil { // 消耗 '}'
372			return err
373		}
374		if _, err := dec.Token(); err != io.EOF {
375			if err == nil {
376				return fmt.Errorf("%s", trailingMsg)
377			}
378			return err
379		}
380	
381		for _, field := range required {
382			if !present[field] {
383				return fmt.Errorf("missing required field %q", field)
384			}
385		}
386		return nil
387	}
388	
389	// readNameField 读取写入与查询共用的指标名字段：必须是非空字符串。
390	func readNameField(dec *json.Decoder, dst *string) error {
391		t, err := dec.Token()
392		if err != nil {
393			return err
394		}
395		s, ok := t.(string)
396		if !ok {
397			return fmt.Errorf(`field "name" must be a string`)
398		}
399		if s == "" {
400			return fmt.Errorf(`field "name" must be a non-empty string`)
401		}
402		*dst = s
403		return nil
404	}
405	
406	// readInt64Field 读取 int64 毫秒整数字段（timestamp/start/end）：
407	// 必须是 JSON 整数且在 int64 范围内，数字字符串、布尔值、带小数点一律拒绝。
408	func readInt64Field(dec *json.Decoder, field string, dst *int64) error {
409		n, err := nextJSONNumber(dec, field)
410		if err != nil {
411			return err
412		}
413		v, err := parseJSONInt(n)
414		if err != nil {
415			return fmt.Errorf("field %q: %s", field, err)
416		}
417		*dst = v
418		return nil
419	}
420	
421	// readFiniteFloatField 读取采样值字段：必须是可表示为有限 float64 的 JSON 数字。
422	func readFiniteFloatField(dec *json.Decoder, field string, dst *float64) error {
423		n, err := nextJSONNumber(dec, field)
424		if err != nil {
425			return err
426		}
427		v, err := parseFiniteFloat(n)
428		if err != nil {
429			return fmt.Errorf("field %q: %s", field, err)
430		}
431		*dst = v
432		return nil
433	}
434	
435	// readLabelsField 读取标签对象字段并写入 dst；notObjectMsg 保留各输入侧措辞。
436	func readLabelsField(dec *json.Decoder, notObjectMsg string, dst *map[string]string) error {
437		labels, err := parseLabels(dec, notObjectMsg)
438		if err != nil {
439			return err
440		}
441		*dst = labels
442		return nil
443	}
444	
445	type parsedSample struct {
446		name   string
447		ts     int64
448		value  float64
449		labels map[string]string
450	}
451	
452	// parseSample 对单个采样点做严格校验：仅允许四个已知字段、拒绝重复键，
453	// 标量必须是精确的 JSON 类型，timestamp 为 int64 整数，value 为有限 float64。
454	func parseSample(raw json.RawMessage) (parsedSample, error) {
455		var p parsedSample
456		p.labels = map[string]string{}
457		err := parseStrictObject(raw,
458			"each sample must be a JSON object",
459			"unexpected content after the sample object",
460			[]string{"name", "timestamp", "value"},
461			map[string]fieldReader{
462				"name":      func(dec *json.Decoder) error { return readNameField(dec, &p.name) },
463				"timestamp": func(dec *json.Decoder) error { return readInt64Field(dec, "timestamp", &p.ts) },
464				"value":     func(dec *json.Decoder) error { return readFiniteFloatField(dec, "value", &p.value) },
465				"labels": func(dec *json.Decoder) error {
466					return readLabelsField(dec, `field "labels" must be an object of string keys to string values`, &p.labels)
467				},
468			})
469		return p, err
470	}
471	
472	// parseLabels 从 dec 读取一个标签对象并做统一校验：必须是 JSON 对象
473	// （否则返回调用方给出的 notObjectMsg，写入与查询措辞不同），键为非空字符串、
474	// 值为字符串（空串合法，键值均不做清理），重复键一律拒绝。
475	// 返回的集合不含标签时也是非 nil 的空 map，与省略 labels 的语义一致。
476	func parseLabels(dec *json.Decoder, notObjectMsg string) (map[string]string, error) {
477		t, err := dec.Token()
478		if err != nil {
479			return nil, err
480		}
481		d, ok := t.(json.Delim)
482		if !ok || d != '{' {
483			return nil, fmt.Errorf("%s", notObjectMsg)
484		}
485		labels := map[string]string{}
486		for dec.More() {
487			labelKeyTok, err := dec.Token()
488			if err != nil {
489				return nil, err
490			}
491			labelKey := labelKeyTok.(string)
492			if labelKey == "" {
493				return nil, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
494			}
495			valTok, err := dec.Token()
496			if err != nil {
497				return nil, err
498			}
499			labelVal, ok := valTok.(string)
500			if !ok {
501				return nil, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
502			}
503			if _, dup := labels[labelKey]; dup {
504				return nil, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
505			}
506			labels[labelKey] = labelVal
507		}
508		if _, err := dec.Token(); err != nil { // 消耗 '}'
509			return nil, err
510		}
511		return labels, nil
512	}
513	
514	func nextJSONNumber(dec *json.Decoder, field string) (json.Number, error) {
515		t, err := dec.Token()
516		if err != nil {
517			return "", err
518		}
519		n, ok := t.(json.Number)
520		if !ok {
521			return "", fmt.Errorf(`field %q must be a JSON number`, field)
522		}
523		return n, nil
524	}
525	
526	func parseJSONInt(n json.Number) (int64, error) {
527		s := string(n)
528		if !jsonIntegerRE.MatchString(s) {
529			return 0, fmt.Errorf("must be a JSON integer in milliseconds")
530		}
531		v, err := strconv.ParseInt(s, 10, 64)
532		if err != nil {
533			return 0, fmt.Errorf("must be within int64 range")
534		}
535		return v, nil
536	}
537	
538	func parseFiniteFloat(n json.Number) (float64, error) {
539		s := string(n)
540		if !jsonNumberRE.MatchString(s) {
541			return 0, fmt.Errorf("must be a JSON number")
542		}
543		v, err := strconv.ParseFloat(s, 64)
544		if err != nil || math.IsInf(v, 0) || math.IsNaN(v) {
545			return 0, fmt.Errorf("must be a finite number representable as float64")
546		}
547		return v, nil
548	}
549	
550	// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
551	func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
552		type pending struct {
553			id  seriesID
554			ref SeriesRef
555			ts  int64
556			val float64
557		}
558	
559		added := 0
560		// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
561		seen := make(map[seriesID]map[int64]float64)
562		// 仅记录需要落盘的新增点；校验全部通过后才提交。
563		commits := make([]pending, 0, len(items))
564	
565		failAt := func(index int, msg string) *LineError {
566			return &LineError{Status: "error", Index: index, Error: msg}
567		}
568		conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
569			return &LineError{
570				Status: "error",
571				Index:  index,
572				Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
573					ref, ts, formatFloat(existing), formatFloat(submitted)),
574				Conflict: &Conflict{
575					// 标签必须复制：冲突结果是本次失败的独立记录，
576					// 调用方修改它不能改动已存序列的身份。
577					Series:    SeriesRef{Name: ref.Name, Labels: cloneLabels(ref.Labels)},
578					Timestamp: ts,
579					Existing:  existing,
580					Submitted: submitted,
581				},
582			}
583		}
584	
585		for i, item := range items {
586			pos := i + 1
587			p, err := parseSample(item)
588			if err != nil {
589				return nil, failAt(pos, err.Error())
590			}
591	
592			id := makeSeriesID(p.name, p.labels)
593			ref := SeriesRef{Name: p.name, Labels: p.labels}
594	
595			if byTS, ok := seen[id]; ok {
596				if old, ok := byTS[p.ts]; ok {
597					if old != p.value {
598						return nil, conflictAt(pos, ref, p.ts, old, p.value)
599					}
600					// 同批内重复出现且数值相同：重复，成功忽略。
601					continue
602				}
603			}
604			if sr, ok := s.series[id]; ok {
605				if old, ok := sr.points[p.ts]; ok {
606					if old != p.value {
607						return nil, conflictAt(pos, sr.ref, p.ts, old, p.value)
608					}
609					// 与此前批次已写入的值相同：重复，成功忽略。
610					if seen[id] == nil {
611						seen[id] = map[int64]float64{}
612					}
613					seen[id][p.ts] = p.value
614					continue
615				}
616			}
617	
618			added++
619			if seen[id] == nil {
620				seen[id] = map[int64]float64{}
621			}
622			seen[id][p.ts] = p.value
623			commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
624		}
625	
626		// 全部采样点合法且无冲突，原子提交本批新增点。
627		for _, c := range commits {
628			sr := s.series[c.id]
629			if sr == nil {
630				sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
631				s.series[c.id] = sr
632			}
633			sr.points[c.ts] = c.val
634		}
635	
636		return s.snapshot(added, len(items)-added), nil
637	}
638	
639	// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
640	func formatFloat(v float64) string {
641		return strconv.FormatFloat(v, 'g', -1, 64)
642	}
643	
644	type parsedQuery struct {
645		name   string
646		start  int64
647		end    int64
648		labels map[string]string
649	}
650	
651	// queryFromObject 严格解析查询对象并执行只读区间均值查询。
652	func (s *MetricStore) queryFromObject(raw json.RawMessage) (*QueryResult, *LineError) {
653		q, err := parseQuery(raw)
654		if err != nil {
655			return nil, &LineError{Status: "error", Error: err.Error()}
656		}
657		if q.start > q.end {
658			return nil, &LineError{Status: "error", Error: fmt.Sprintf(
659				`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
660		}
661		return s.runQuery(q), nil
662	}
663	
664	// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
665	// 拒绝重复键与未知字段；标量必须是精确的 JSON 类型，start/end 为 int64 毫秒。
666	func parseQuery(raw json.RawMessage) (parsedQuery, error) {
667		var q parsedQuery
668		err := parseStrictObject(raw,
669			"each query must be a JSON object",
670			"unexpected content after the query object",
671			[]string{"op", "name", "start", "end"},
672			map[string]fieldReader{
673				"op": func(dec *json.Decoder) error {
674					t, err := dec.Token()
675					if err != nil {
676						return err
677					}
678					op, ok := t.(string)
679					if !ok {
680						return fmt.Errorf(`field "op" must be a string`)
681					}
682					if op != "query" {
683						return fmt.Errorf(`unknown op %q (only "query" is supported)`, op)
684					}
685					return nil
686				},
687				"name":  func(dec *json.Decoder) error { return readNameField(dec, &q.name) },
688				"start": func(dec *json.Decoder) error { return readInt64Field(dec, "start", &q.start) },
689				"end":   func(dec *json.Decoder) error { return readInt64Field(dec, "end", &q.end) },
690				"labels": func(dec *json.Decoder) error {
691					return readLabelsField(dec, `field "labels" must be an object of non-empty string keys to string values`, &q.labels)
692				},
693			})
694		return q, err
695	}
696	
697	// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
698	// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
699	func labelsMatch(want, stored map[string]string) bool {
700		for k, v := range want {
701			got, ok := stored[k]
702			if !ok || got != v {
703				return false
704			}
705		}
706		return true
707	}
708	
709	// runQuery 只读扫描已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
710	// 序列次序与写入快照共用 organizeSeries 的整理结果：过滤掉其他序列后，
711	// 保留的序列仍是同一排序中的一个子序列，不另换排序；无区间内点的序列不列出。
712	func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
713		inRange := func(ts int64) bool { return ts >= q.start && ts <= q.end }
714		out := make([]QuerySeries, 0)
715		for _, os := range s.organizeSeries() {
716			if os.ref.Name != q.name || !labelsMatch(q.labels, os.ref.Labels) {
717				continue
718			}
719			points := sortedSeriesPoints(os.sr, inRange)
720			if len(points) == 0 {
721				continue
722			}
723			values := make([]float64, len(points))
724			for i, p := range points {
725				values[i] = p.Value
726			}
727			out = append(out, QuerySeries{
728				Name:    os.ref.Name,
729				Labels:  os.ref.Labels,
730				Count:   len(values),
731				Average: finiteMean(values),
732			})
733		}
734		return &QueryResult{Status: "ok", Op: "query", Series: out}
735	}
736	
737	// finiteMean 返回已存储 float64 值的精确算术平均所对应的最近 float64，
738	// 恰好在两个相邻可表示值中间时按最近偶数舍入。
739	// 求和用有理数精确完成：与点的顺序、批次划分无关，正负大数抵消后的小余量
740	// 不会丢失，总和超出 float64 范围时结果仍然有限。精确平均为零时返回 +0；
741	// 只有一个点时结果就是该点的值。
742	func finiteMean(values []float64) float64 {
743		sum := new(big.Rat)
744		r := new(big.Rat)
745		for _, v := range values {
746			// 写入侧已保证 v 有限，SetFloat64 对有限值是精确的。
747			sum.Add(sum, r.SetFloat64(v))
748		}
749		sum.Quo(sum, r.SetInt64(int64(len(values))))
750		return ratToFloat64NearestEven(sum)
751	}
752	
753	// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
754	// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
755	func ratToFloat64NearestEven(x *big.Rat) float64 {
756		if x.Sign() == 0 {
757			return 0
758		}
759		num := new(big.Int).Set(x.Num())
760		den := x.Denom()
761		neg := num.Sign() < 0
762		if neg {
763			num.Neg(num)
764		}
765	
766		// e 满足 2^e <= num/den < 2^(e+1)。
767		e := floorLog2Rat(num, den)
768		var m *big.Int
769		scale := 0
770		if e >= -1022 {
771			// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
772			scale = e - 52
773			m = roundScaledRatio(num, den, scale)
774			if m.BitLen() == 54 {
775				// 舍入进位（如 1.111…1 进为 10.0），指数加一。
776				m.Rsh(m, 1)
777				scale++
778			}
779		} else {
780			// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
781			scale = -1074
782			m = roundScaledRatio(num, den, scale)
783		}
784		// m < 2^53，可以精确放入 int64 与 float64。
785		f := math.Ldexp(float64(m.Int64()), scale)
786		if neg {
787			return -f
788		}
789		return f
790	}
791	
792	// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
793	func floorLog2Rat(num, den *big.Int) int {
794		k := num.BitLen() - den.BitLen()
795		var t big.Int
796		if k >= 0 {
797			t.Lsh(den, uint(k))
798			if num.Cmp(&t) >= 0 {
799				return k
800			}
801			return k - 1
802		}
803		t.Lsh(num, uint(-k))
804		if t.Cmp(den) >= 0 {
805			return k
806		}
807		return k - 1
808	}
809	
810	// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
811	func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
812		n := new(big.Int).Set(num)
813		d := new(big.Int).Set(den)
814		if scale >= 0 {
815			d.Lsh(d, uint(scale))
816		} else {
817			n.Lsh(n, uint(-scale))
818		}
819		q, r := new(big.Int).QuoRem(n, d, new(big.Int))
820		switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
821		case 1:
822			q.Add(q, big.NewInt(1))
823		case 0:
824			if q.Bit(0) == 1 {
825				q.Add(q, big.NewInt(1))
826			}
827		}
828		return q
829	}
830	
831	// String 让冲突原因中的序列身份可读：name{k=v,...}，标签按键排序。
832	func (r SeriesRef) String() string {
833		var b strings.Builder
834		b.WriteString(r.Name)
835		b.WriteByte('{')
836		for i, p := range sortedPairs(r.Labels) {
837			if i > 0 {
838				b.WriteByte(',')
839			}
840			fmt.Fprintf(&b, "%s=%s", p.Key, p.Value)
841		}
842		b.WriteByte('}')
843		return b.String()
844	}
845	
846	// organizedSeries 是一次结果整理中的一条序列：携带已存序列指针，
847	// 以及供结果直接使用的独立标签副本（标签书写顺序不影响身份，
848	// 副本使调用方对结果的修改不能回写存储）。
849	type organizedSeries struct {
850		sr  *storedSeries
851		ref SeriesRef
852	}
853	
854	// organizeSeries 是写入快照与区间查询共用的数据整理逻辑：
855	// 遍历全部已提交序列，复制各自的序列身份，并按唯一的顺序约定排列——
856	// 先按指标名字符串字典序，再按标签键升序后的键值对逐对比较
857	// （先比键再比值，前一对相同才比下一对；较短集合是完整前缀时排前，
858	// 无标签序列因此排在最前）。标签值按字符串比较（"10" 在 "2" 之前）。
859	// 整理结果不复制采样点；采样点的选取与升序排列由 sortedSeriesPoints 完成。
860	func (s *MetricStore) organizeSeries() []organizedSeries {
861		out := make([]organizedSeries, 0, len(s.series))
862		for _, sr := range s.series {
863			// 标签必须复制：成功结果是当次操作的独立记录，
864			// 调用方修改结果标签不能改动已存序列的身份。
865			out = append(out, organizedSeries{
866				sr:  sr,
867				ref: SeriesRef{Name: sr.ref.Name, Labels: cloneLabels(sr.ref.Labels)},
868			})
869		}
870		sort.Slice(out, func(i, j int) bool {
871			if out[i].ref.Name != out[j].ref.Name {
872				return out[i].ref.Name < out[j].ref.Name
873			}
874			return compareLabelPairs(sortedPairs(out[i].ref.Labels), sortedPairs(out[j].ref.Labels)) < 0
875		})
876		return out
877	}
878	
879	// sortedSeriesPoints 按 timestamp 升序返回一条已存序列中满足 keep 的采样点，
880	// 数值与时间戳一一对应。keep 为 nil 时返回全部点（写入快照）；
881	// 区间查询传入闭区间判定，查询只选取区间内的点。
882	// 返回的是新建切片与新建 Point，调用方对采样点的修改不影响存储，
883	// 也不影响此前或此后取得的其他成功结果。
884	func sortedSeriesPoints(sr *storedSeries, keep func(ts int64) bool) []Point {
885		tsList := make([]int64, 0, len(sr.points))
886		for ts := range sr.points {
887			if keep == nil || keep(ts) {
888				tsList = append(tsList, ts)
889			}
890		}
891		sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
892		points := make([]Point, len(tsList))
893		for i, ts := range tsList {
894			points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
895		}
896		return points
897	}
898	
899	// snapshot 生成按规范排序的全部序列视图：序列次序与点排列均来自
900	// organizeSeries/sortedSeriesPoints 这套与查询共用的整理逻辑。
901	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
902		organized := s.organizeSeries()
903		views := make([]SeriesView, 0, len(organized))
904		for _, os := range organized {
905			views = append(views, SeriesView{
906				Name:   os.ref.Name,
907				Labels: os.ref.Labels,
908				Points: sortedSeriesPoints(os.sr, nil),
909			})
910		}
911		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
912	}
